/bin/bash -lc "python3 - <<'PY'
import os, sys, json, shutil, subprocess
from pathlib import Path

def read(path):
    try:
        return Path(path).read_text().strip()
    except OSError:
        return None

mem = {}
for line in (read('/proc/meminfo') or '').splitlines():
    key, value = line.split(':', 1)
    if key in ('MemTotal', 'MemAvailable', 'SwapTotal', 'SwapFree'):
        mem[key + '_bytes'] = int(value.split()[0]) * 1024

membership = read('/proc/self/cgroup')
mounts = []
for line in (read('/proc/self/mountinfo') or '').splitlines():
    left, right = line.split(' - ', 1)
    fields, tail = left.split(), right.split()
    if tail[0] in ('cgroup', 'cgroup2'):
        mounts.append((fields[3], fields[4], tail[0], tail[2]))

chains = []
for entry in (membership or '').splitlines():
    _, controllers, group = entry.split(':', 2)
    for root, mount, kind, options in mounts:
        if kind == 'cgroup' and not set(controllers.split(',')).intersection(options.split(',')):
            continue
        if kind == 'cgroup2' and controllers:
            continue
        relative = group[len(root):].lstrip('/') if group == root or group.startswith(root.rstrip('/') + '/') else None
        if relative is None:
            continue
        current, boundary = Path(mount) / relative, Path(mount)
        levels = []
        while True:
            names = ('memory.max', 'memory.high', 'memory.current', 'memory.swap.max', 'cpu.max', 'cpuset.cpus.effective') if kind == 'cgroup2' else ('memory.limit_in_bytes', 'memory.memsw.limit_in_bytes', 'cpu.cfs_quota_us', 'cpu.cfs_period_us', 'cpuset.cpus')
            values = {name: value for name in names if (value := read(current / name)) is not None}
            levels.append({'path': str(current), 'values': values})
            if current == boundary:
                break
            current = current.parent
        chains.append({'kind': kind, 'controllers': controllers, 'levels_leaf_to_visible_root': levels})

memory_caps, cpu_caps = [], []
for chain in chains:
    for level in chain['levels_leaf_to_visible_root']:
        v = level['values']
        m = v.get('memory.max', v.get('memory.limit_in_bytes'))
        if m and m "'!= '"'max':
            memory_caps.append(int(m))
        if 'cpu.max' in v:
            quota, period = v['cpu.max'].split()
            if quota "'!= '"'max':
                cpu_caps.append(int(quota) / int(period))
        elif int(v.get('cpu.cfs_quota_us', '-1')) > 0 and 'cpu.cfs_period_us' in v:
            cpu_caps.append(int(v['cpu.cfs_quota_us']) / int(v['cpu.cfs_period_us']))

tools = {}
for name in ('cmake', 'g++', 'ffmpeg', 'python', 'python3'):
    executable = shutil.which(name)
    info = {'present': executable is not None, 'path': executable}
    if executable:
        result = subprocess.run([executable, '-version' if name == 'ffmpeg' else '--version'], capture_output=True, text=True, timeout=10)
        lines = (result.stdout + result.stderr).splitlines()
        info.update(version=lines[0] if lines else None, exit_code=result.returncode)
    tools[name] = info

usage = shutil.disk_usage('/workspace')
result = {
    'scope': 'current VM; read-only; no candidate trial',
    'memory_proc': mem,
    'cpu': {'logical_os_count': os.cpu_count(), 'affinity_logical_count': len(os.sched_getaffinity(0))},
    'cgroup': {'membership': membership, 'chains': chains, 'minimum_visible_memory_cap_bytes': min(memory_caps) if memory_caps else None, 'minimum_visible_cpu_quota_cores': min(cpu_caps) if cpu_caps else None, 'limit_scope': 'visible ancestors only; hidden host ancestors cannot be assessed'},
    'workspace_disk': {'path': '/workspace', 'total_bytes': usage.total, 'free_bytes': usage.free},
    'tools': tools,
    'existing_writable_directories': [{'path': p, 'is_directory': os.path.isdir(p), 'owned_by_current_uid': os.stat(p).st_uid == os.getuid() if os.path.exists(p) else None, 'write_and_search_os_access': os.access(p, os.W_OK | os.X_OK), 'created_or_write_tested': False} for p in ('/workspace', '/tmp')],
    'candidate_fit': 'unknown; weight size and MemAvailable do not establish peak RAM or feasibility'
}
print(json.dumps(result, ensure_ascii=False, indent=2))
PY"

